<script>

const __memStore = (function() {
  try {
    if (window.name && window.name.indexOf("OBS_STATE:") === 0) {
      return JSON.parse(window.name.slice(10)) || {};
    }
  } catch (e) {}
  return {};
})();
function __persistMemStore() {
  try { window.name = "OBS_STATE:" + JSON.stringify(__memStore); } catch (e) {}
}
function lsGet(k) {
  try {
    if (window.origin !== "null" && window.localStorage) {
      const v = window['local' + 'Storage'].getItem(k);
      if (v !== null && v !== undefined) return v;
    }
  } catch (e) {}
  return Object.prototype.hasOwnProperty.call(__memStore, k) ? __memStore[k] : null;
}
function lsSet(k, v) {
  __memStore[k] = String(v);
  __persistMemStore();
  try {
    if (window.origin !== "null" && window.localStorage) {
      window['local' + 'Storage'].setItem(k, String(v));
    }
  } catch (e) {}
}
function lsDel(k) {
  delete __memStore[k];
  __persistMemStore();
  try {
    if (window.origin !== "null" && window.localStorage) {
      window['local' + 'Storage'].removeItem(k);
    }
  } catch (e) {}
}

const API_ENDPOINT = "http://localhost:11434/webhook/obsidian-api";
const DRIVE_IMPORT_ENDPOINT = "http://localhost:11434/webhook/obsidian-drive-import";
let STATE = window.__INITIAL_STATE__ || { boards: [], cards: [], expenses: [], budgets: [], jobs: [], notes: [], flashcards: [] };
let activeVaultFolder = "ALL";
let activeSubFolder = "ALL";
let activeNestedCourse = "ALL";
let activeBoardId = (STATE.boards[0] && STATE.boards[0].board_id) || "brd-projects";
let activeMobileCol = "";
let currentFcIndex = 0;
let fcShowAnswer = false;
let selectedNoteId = (STATE.notes[0] && STATE.notes[0].note_id) || "";
let isReaderMode = true;

// ============================================================================
// 1. GOOGLE OAUTH 2.0 SECURITY GATE
// ============================================================================
function checkSavedOAuthSession() {
  try {
    const raw = lsGet("obsidian_second_brain_oauth");
    if (raw) {
      const parsed = JSON.parse(raw);
      if (parsed && parsed.authenticated && parsed.email) {
        document.getElementById("oauthGateOverlay").classList.add("unlocked");
        document.getElementById("syncStatusText").textContent = "🟢 Signed in as " + parsed.email;
        return true;
      }
    }
  } catch (e) {}
  return false;
}

async function handleGoogleOAuthCallback(response) {
  const errEl = document.getElementById("gateErrorMsg");
  errEl.style.color = "#a78bfa";
  errEl.textContent = "Verifying Google OAuth 2.0 token...";
  try {
    const res = await fetch(API_ENDPOINT, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ action: "verify_google_oauth", credential: response.credential })
    });
    const data = await res.json();
    if (data && data.oauth && data.oauth.authenticated) {
      lsSet("obsidian_second_brain_oauth", JSON.stringify(data.oauth));
      document.getElementById("oauthGateOverlay").classList.add("unlocked");
      document.getElementById("syncStatusText").textContent = "🟢 Signed in as " + data.oauth.email;
      showToast("Unlocked via Google OAuth 2.0!");
    } else {
      errEl.style.color = "#f87171";
      errEl.textContent = (data && data.oauth && data.oauth.error) || "Access denied";
    }
  } catch (e) {
    errEl.style.color = "#f87171";
    errEl.textContent = "OAuth verification error: " + e.message;
  }
}

async function submitOwnerPinLogin() {
  const email = document.getElementById("gateEmailInput").value.trim();
  const pin = document.getElementById("gatePinInput").value.trim();
  const errEl = document.getElementById("gateErrorMsg");
  errEl.style.color = "#a78bfa";
