      errEl.textContent = (data && data.oauth && data.oauth.error) || "Invalid PIN or email";
    }
  } catch (e) {
    errEl.style.color = "#f87171";
    errEl.textContent = "Error: " + e.message;
  }
}

function lockAppSession() {
