// ============================================================================
// 2. 1-TAP GLOBAL VAULT SWITCHER & MOBILE/DESKTOP VIEW
// ============================================================================
function cleanVaultId(v) {
  const s = String(v || "Education").trim().replace(/^\d+_/, "");
  return s || "Education";
}

function prettyVaultName(v) {
  if (!v || v === "ALL") return "All Vaults";
  return String(v)
    .split("/")
    .map(seg => seg.replace(/^\d+_/, "").replace(/_/g, " ").replace(/And/g, "&"))
    .join(" › ");
}

function getParentVaultOfNote(note) {
  return cleanVaultId(String((note && note.folder) || "Education").split("/")[0]);
}

function getSubfolderOfNote(note) {
  const parts = String((note && note.folder) || "").split("/");
  return parts.length > 1 ? parts.slice(1).join("/").replace(/^\d+_/, "") : "";
}

function getNestedCourseOfNote(note) {
  const m = String((note && note.title) || "").match(/^\[([^\]]+)\]/);
  return m ? m[1].trim() : "";
}

function getSubfoldersForVault(parentVault) {
  const targetPv = parentVault === "ALL" ? "ALL" : cleanVaultId(parentVault);
  const set = new Set();
  for (const n of (STATE.notes || [])) {
    const pv = getParentVaultOfNote(n);
    const sf = getSubfolderOfNote(n);
    if ((targetPv === "ALL" || pv === targetPv) && sf) {
      set.add(sf);
    }
  }
  return Array.from(set).sort();
}

function selectGlobalVault(vaultFolder, targetSubFolder) {
  const parts = String(vaultFolder || "ALL").split("/");
  const baseVault = parts[0] === "ALL" ? "ALL" : cleanVaultId(parts[0]);
  const impliedSub = parts.length > 1 ? parts.slice(1).join("/").replace(/^\d+_/, "") : (targetSubFolder || "ALL");

  activeVaultFolder = baseVault;
  activeSubFolder = impliedSub;
  activeNestedCourse = "ALL";

  document.querySelectorAll("#globalVaultSwitcherBar .vault-pill").forEach(btn => {
    btn.classList.toggle("active", btn.getAttribute("data-vault") === baseVault);
  });

  const vfSel = document.getElementById("vaultFolderFilter");
  if (vfSel) vfSel.value = baseVault;
  const impSel = document.getElementById("importTargetFolder");
  if (impSel && baseVault !== "ALL" && baseVault !== "Daily") impSel.value = baseVault;

  const boardMap = {
    "Education": "brd-education",
    "Business_Ideas": "brd-business",
    "LouLou_And_Luxe": "brd-loulou",
    "Projects": "brd-projects"
  };
  if (boardMap[baseVault] && STATE.boards.find(b => b.board_id === boardMap[baseVault])) {
    activeBoardId = boardMap[baseVault];
    activeMobileCol = "";
  }

  const matchingNotes = STATE.notes.filter(n => {
    if (baseVault !== "ALL" && getParentVaultOfNote(n) !== baseVault) return false;
    if (activeSubFolder !== "ALL") {
      if (activeSubFolder === "__ROOT__" && getSubfolderOfNote(n) !== "") return false;
      if (activeSubFolder !== "__ROOT__" && getSubfolderOfNote(n) !== activeSubFolder) return false;
    }
    return true;
  });
  if (matchingNotes.length > 0) {
    selectedNoteId = matchingNotes[0].note_id;
  }

  setReaderMode(true);
  renderAll();

  if (baseVault !== "ALL") {
    switchTab("learning");
  }
}

function selectVaultSubfolder(subName) {
  activeSubFolder = subName;
  activeNestedCourse = "ALL";
