async function deleteActiveSubfolder() {
  if (!activeVaultFolder || activeVaultFolder === "ALL" || !activeSubFolder || activeSubFolder === "ALL" || activeSubFolder === "__ROOT__") return;
  const fullPath = `${activeVaultFolder}/${activeSubFolder}`;
