function openNoteByWikiLink(rawTarget) {
  const target = String(rawTarget || "").trim().replace(/\.md$/i, "");
  if (!target) return;
  const lower = target.toLowerCase();
  const baseTarget = lower.split("/").pop().replace(/^\d+[\s_\-]+/, "").replace(/_/g, " ").trim();
  const match = (STATE.notes || []).find(n => {
    const fp = String(n.file_path || "").replace(/\.md$/i, "").toLowerCase();
    const fpStem = fp.split("/").pop().replace(/_/g, " ");
    const ttl = String(n.title || "").toLowerCase();
    return fp === lower || fp.endsWith("/" + lower) || fpStem === baseTarget || ttl === lower || ttl.endsWith("] " + baseTarget) || ttl.includes(baseTarget);
  });
  if (match) {
    selectedNoteId = match.note_id;
    renderLearningTab();
    showToast(`Opened [[${match.title}]]`);
  } else {
    showToast(`Note "${target}" not found in current Vault`, true);
  }
}

