function esc(s) {
  return String(s === null || s === undefined ? "" : s)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

// ============================================================================
// 3. RICH MARKDOWN & GOOGLE SHEET TABLE RENDERER (FOR 📖 READER MODE)
// ============================================================================
function renderMarkdownToHtml(rawMd) {
  if (!rawMd) return `<div style="color:var(--text-muted);">Empty note. Tap '✏️ Edit Markdown' to write content.</div>`;
  let text = String(rawMd).replace(/\r\n/g, "\n");

  // 1. Parse YAML frontmatter if present
  let metaHtml = "";
  const fmMatch = text.match(/^---\n([\s\S]*?)\n---\n*/);
  if (fmMatch) {
    text = text.slice(fmMatch[0].length);
    const fmLines = fmMatch[1].split("\n");
    const meta = {};
    fmLines.forEach(l => {
      const idx = l.indexOf(":");
      if (idx > 0) {
        const k = l.slice(0, idx).trim();
        const v = l.slice(idx + 1).trim().replace(/^"|"$/g, "");
        meta[k] = v;
      }
    });
    const badges = [];
    if (meta.folder) badges.push(`<span class="badge badge-tag">📂 ${esc(prettyVaultName(meta.folder))}</span>`);
    if (meta.source_type) badges.push(`<span class="badge badge-Medium">🔗 ${esc(meta.source_type)}</span>`);
    if (meta.source_url) badges.push(`<a class="btn btn-sm btn-primary" href="${esc(meta.source_url)}" target="_blank">↗ Open Source Google Doc/Sheet</a>`);
    if (badges.length) {
      metaHtml = `<div class="md-meta-bar">${badges.join("")}</div>`;
    }
  }

  function formatInline(str) {
    let s = esc(str);
    s = s.replace(/!\[([^\]]*)\]\((https?:\/\/[^\s)]+)\)/g, `<div style="margin:10px 0;"><img src="$2" alt="$1" style="max-width:100%; max-height:460px; border-radius:10px; border:1px solid var(--border); display:block;" loading="lazy" /></div>`);
    s = s.replace(/&lt;br\s*\/?&gt;/gi, "<br/>");
    s = s.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
    s = s.replace(/\*([^*]+)\*\*/g, "<strong>$1</strong>");
    s = s.replace(/\*([^*]+)\*/g, "<em>$1</em>");
    s = s.replace(/`([^`]+)`/g, "<code>$1</code>");
    s = s.replace(/\[\[([^\]|]+)\|([^\]]+)\]\]/g, `<button type="button" class="wiki-link-pill" data-wikilink="$1" onclick="openNoteByWikiLink(this.getAttribute('data-wikilink'))">🔗 $2</button>`);
    s = s.replace(/\[\[([^\]]+)\]\]/g, `<button type="button" class="wiki-link-pill" data-wikilink="$1" onclick="openNoteByWikiLink(this.getAttribute('data-wikilink'))">🔗 $1</button>`);
    s = s.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, `<a href="$2" target="_blank">$1 ↗</a>`);
    return s;
  }

  const lines = text.split("\n");
  let html = metaHtml;
  let inTable = false;
  let tableRows = [];
  let inList = false;

  function flushTable() {
    if (!inTable || !tableRows.length) return;
    inTable = false;
    const parseRow = r => r.replace(/^\||\|$/g, "").split(/(?<!\\)\|/).map(c => c.replace(/\\\|/g, "|").trim());
    const headerCells = parseRow(tableRows[0]);
    let tHtml = `<div class="md-table-wrap"><table><thead><tr>` + headerCells.map(h => `<th>${formatInline(h)}</th>`).join("") + `</tr></thead><tbody>`;
    for (let i = 1; i < tableRows.length; i++) {
      if (/^[\s|:\-]+$/.test(tableRows[i])) continue;
      const cells = parseRow(tableRows[i]);
      tHtml += `<tr>` + cells.map(c => `<td>${formatInline(c)}</td>`).join("") + `</tr>`;
    }
    tHtml += `</tbody></table></div>`;
    html += tHtml;
    tableRows = [];
  }

  function flushList() {
    if (inList) {
      html += `</ul>`;
      inList = false;
    }
  }

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();

    if (trimmed.startsWith("|") && trimmed.endsWith("|")) {
      flushList();
      inTable = true;
      tableRows.push(trimmed);
      continue;
    } else if (inTable) {
      flushTable();
    }

    if (!trimmed) {
      flushList();
      continue;
    }

    if (trimmed.startsWith("# ")) {
      flushList();
      html += `<h1>${formatInline(trimmed.slice(2))}</h1>`;
    } else if (trimmed.startsWith("## ")) {
      flushList();
      html += `<h2>${formatInline(trimmed.slice(3))}</h2>`;
    } else if (trimmed.startsWith("### ")) {
      flushList();
      html += `<h3>${formatInline(trimmed.slice(4))}</h3>`;
    } else if (trimmed.startsWith("> ")) {
      flushList();
      const cleanQuote = trimmed.slice(2).replace(/^\[!([a-zA-Z]+)\]\s*/, (_, t) => `<strong>📌 ${t.toUpperCase()}:</strong> `);
      html += `<div class="md-callout">${formatInline(cleanQuote)}</div>`;
    } else if (trimmed.startsWith("- [ ] ") || trimmed.startsWith("- [x] ")) {
      if (!inList) { html += `<ul style="list-style:none; margin-left:4px;">`; inList = true; }
      const checked = trimmed.startsWith("- [x] ");
      html += `<li><input type="checkbox" ${checked ? "checked" : ""} disabled style="width:14px;height:14px;margin-right:6px;" /> ${formatInline(trimmed.slice(6))}</li>`;
    } else if (trimmed.startsWith("- ") || trimmed.startsWith("* ") || /^\d+\.\s/.test(trimmed)) {
      if (!inList) { html += `<ul>`; inList = true; }
      const itemText = trimmed.replace(/^(-|\*|\d+\.)\s+/, "");
      html += `<li>${formatInline(itemText)}</li>`;
    } else if (trimmed.startsWith("#### ")) {
      flushList();
      html += `<h3 style="font-size:13px; color:var(--accent-hover);">${formatInline(trimmed.slice(5))}</h3>`;
    } else if (trimmed === "---") {
      flushList();
      html += `<hr style="border:none;border-top:1px solid var(--border);margin:14px 0;" />`;
    } else if (trimmed.startsWith("<!-- PDF_PREVIEW:") && trimmed.endsWith("-->")) {
      flushList();
      const pdfId = trimmed.replace("<!-- PDF_PREVIEW:", "").replace("-->", "").trim();
      html += `<div style="margin:12px 0; border-radius:10px; overflow:hidden; border:1px solid var(--border); background:#111;"><iframe src="https://drive.google.com/file/d/${esc(pdfId)}/preview" style="width:100%; height:480px; border:none; display:block;" allow="autoplay"></iframe></div>`;
    } else {
      flushList();
      html += `<p>${formatInline(trimmed)}</p>`;
    }
  }
  flushTable();
  flushList();
  return html;
}

function setReaderMode(readerOn) {
  isReaderMode = readerOn;
  const rBox = document.getElementById("vaultReaderViewBox");
  const eBox = document.getElementById("vaultEditorViewBox");
  const btn = document.getElementById("toggleReaderEditBtn");
  if (rBox && eBox && btn) {
    rBox.style.display = isReaderMode ? "block" : "none";
    eBox.style.display = isReaderMode ? "none" : "block";
    btn.innerHTML = isReaderMode ? "✏️ Edit Markdown" : "📖 Reader Mode";
  }
}

function toggleReaderEditMode() {
  setReaderMode(!isReaderMode);
  renderLearningTab();
}

async function apiCall(payload, toastMsg) {
  try {
    const res = await fetch(API_ENDPOINT, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
    const data = await res.json();
    if (data && data.state) {
      STATE = data.state;
      renderAll();
    }
    if (toastMsg) showToast(toastMsg);
    return data;
  } catch (err) {
    showToast("Error: " + err.message, true);
  }
}

function switchTab(tabId) {
  document.querySelectorAll(".nav-tab").forEach(b => b.classList.toggle("active", b.getAttribute("data-tab") === tabId));
  document.querySelectorAll(".m-nav-btn").forEach(b => b.classList.toggle("active", b.getAttribute("data-mtab") === tabId));
  document.querySelectorAll(".tab-pane").forEach(p => p.classList.toggle("active", p.id === "tab-" + tabId));
}

function updateQcPlaceholder() {
  const t = document.getElementById("qcType").value;
  const inp = document.getElementById("qcInput");
  if (t === "expense") inp.placeholder = "e.g. '650 Dinner #food'...";
  else if (t === "task") inp.placeholder = "e.g. 'Review LouLou collection specs'...";
  else if (t === "note") inp.placeholder = "Quick bullet for today's Daily Log...";
  else if (t === "flashcard") inp.placeholder = "'Question ? Answer'...";
}

async function submitQuickCapture() {
  const t = document.getElementById("qcType").value;
  const raw = document.getElementById("qcInput").value.trim();
  if (!raw) return;
  document.getElementById("qcInput").value = "";

  if (t === "expense") {
    const m = raw.match(/(\d+(?:\.\d{1,2})?)/);
    const amount = m ? parseFloat(m[1]) : 0;
    const title = raw.replace(/₹|rs\.?|inr/gi, "").replace(/\b\d+(?:\.\d{1,2})?\b/, "").trim() || "Expense";
    await apiCall({
      action: "save_expense",
      tx_date: new Date().toISOString().slice(0, 10),
      title, amount, currency: "INR", category: "Food & Dining", payment_mode: "UPI", project_tag: "Personal"
    }, `Logged ₹${amount}`);
  } else if (t === "task") {
    await apiCall({
      action: "save_card",
      board_id: activeBoardId || "brd-projects",
      column_name: "To Do",
      title: raw,
      priority: "High",
      due_date: new Date().toISOString().slice(0, 10)
    }, "Task added to Kanban!");
  } else if (t === "note") {
    const todayIso = new Date().toISOString().slice(0, 10);
    const existing = STATE.notes.find(n => n.note_id === "note-daily-" + todayIso);
    const baseMd = existing ? existing.content_md : `# 📅 Daily Log — ${todayIso}\n`;
    await apiCall({
      action: "save_note",
      note_id: "note-daily-" + todayIso,
      folder: "Daily",
      title: `${todayIso} — Daily Log`,
      file_path: `Daily/${todayIso}.md`,
      tags: "#daily",
      content_md: baseMd + "\n- " + raw,
      pinned: true
    }, "Added to Today's Daily Log!");
  } else if (t === "flashcard") {
    const parts = raw.split("?");
    await apiCall({
      action: "save_flashcard",
      deck: "Education",
      question: (parts[0] || raw).trim() + "?",
      answer: (parts.slice(1).join("?") || "See notes").trim()
    }, "Flashcard saved!");
  }
}


