// ============================================================================
const DRIVE_BROWSE_ENDPOINT = "http://localhost:11434/webhook/obsidian-drive-browse";
let driveBreadcrumbs = [{ id: "root", name: "🏠 My Drive" }];
let driveCurrentFolders = [];
let driveCurrentFiles = [];
let driveSelectedMap = {}; // id -> file object
let driveTargetVault = "Education";

function escapeHtml(s) { return String(s === null || s === undefined ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;"); }

let googleOAuthAccessToken = lsGet("obsidian_google_drive_access_token") || "";
let gapiPickerLoaded = false;

function ensureGapiPickerLoaded(cb) {
  if (gapiPickerLoaded && window.google && window.google.picker) {
    cb(true);
    return;
  }
  if (window.gapi && window.gapi.load) {
    window.gapi.load("picker", {
      callback: function() {
        gapiPickerLoaded = true;
        cb(true);
      },
      onerror: function() { cb(false); }
    });
  } else {
    cb(false);
  }
}

function launchOfficialGoogleDrivePicker() {
  const stEl = document.getElementById("driveBrowserModalStatus");
  if (!window.google || !window.google.accounts || !window.google.accounts.oauth2) {
    stEl.style.color = "#f87171";
    stEl.textContent = "Google OAuth script is still loading—please try again in 2 seconds.";
    return;
  }
  stEl.style.color = "#93c5fd";
  stEl.textContent = "Opening Google OAuth account selector...";

  const tokenClient = window.google.accounts.oauth2.initTokenClient({
    client_id: "717762328687-iludtf96g1hinl76e4lc1b9a82g457nn.apps.googleusercontent.com",
    scope: "https://www.googleapis.com/auth/drive.readonly",
    prompt: "select_account",
    callback: async function(tokenResponse) {
      if (tokenResponse && tokenResponse.access_token) {
        googleOAuthAccessToken = tokenResponse.access_token;
        lsSet("obsidian_google_drive_access_token", googleOAuthAccessToken);
        stEl.style.color = "#34d399";
        stEl.textContent = "✅ Google OAuth connected! Loading your Google Drive...";

        // Try launching Google's native Picker UI first, and ALSO load the authenticated account's Drive directly!
        ensureGapiPickerLoaded(function(ok) {
          if (ok && window.google && window.google.picker) {
            try {
              const viewAll = new google.picker.DocsView(google.picker.ViewId.DOCS)
                .setIncludeFolders(true)
                .setSelectFolderEnabled(true)
                .setMode(google.picker.DocsViewMode.LIST);
              const viewShared = new google.picker.DocsView(google.picker.ViewId.DOCS)
                .setOwnedByMe(false)
                .setIncludeFolders(true)
                .setSelectFolderEnabled(true)
                .setLabel("Shared with me");
              const viewFolders = new google.picker.DocsView(google.picker.ViewId.FOLDERS)
                .setIncludeFolders(true)
                .setSelectFolderEnabled(true)
                .setLabel("Folders");

              const picker = new google.picker.PickerBuilder()
                .enableFeature(google.picker.Feature.MULTISELECT_ENABLED)
                .setAppId("717762328687")
                .setOAuthToken(googleOAuthAccessToken)
                .addView(viewAll)
                .addView(viewShared)
                .addView(viewFolders)
                .setTitle("Select Files or Folders for Vault: " + driveTargetVault)
                .setCallback(function(data) {
                  if (data[google.picker.Response.ACTION] === google.picker.Action.PICKED) {
                    const docs = data[google.picker.Response.DOCUMENTS] || [];
                    for (const d of docs) {
                      driveSelectedMap[d.id] = {
                        id: d.id,
                        name: d.name || "Selected File",
                        mimeType: d.mimeType || "",
                        webViewLink: d.url || ("https://drive.google.com/file/d/" + d.id + "/view")
                      };
                    }
                    updateDriveSelectionBadge();
                    renderDriveBrowserList();
                    stEl.style.color = "#34d399";
                    stEl.textContent = `✅ Picked ${docs.length} item(s) from Google Picker! Confirm your target Vault below and click Create Shortcut(s).`;
                  }
                })
                .build();
              picker.setVisible(true);
            } catch (pickerErr) {
              // If GCP project hasn't enabled Picker iframe, load directly via Drive v3 REST API using the user's OAuth token!
              loadDriveDirectWithOAuthToken("root", "");
            }
          } else {
            loadDriveDirectWithOAuthToken("root", "");
          }
        });
        // Also populate the browser list using the exact Google account you just authenticated with!
        loadDriveDirectWithOAuthToken("root", "");
      } else {
        stEl.style.color = "#f87171";
        stEl.textContent = "Google OAuth cancelled or failed.";
      }
    }
  });

  tokenClient.requestAccessToken();
}

async function loadDriveDirectWithOAuthToken(folderId, queryStr) {
  if (!googleOAuthAccessToken) return;
  const box = document.getElementById("driveBrowserListContainer");
  try {
    let q = "trashed = false and mimeType != 'application/vnd.google-apps.shortcut'";
    if (queryStr) {
      q += " and name contains '" + queryStr.replace(/'/g, "\\'") + "'";
    } else if (folderId === "root") {
      q += " and ('root' in parents or sharedWithMe = true)";
    } else {
      q += " and '" + folderId + "' in parents";
    }
    const url = "https://www.googleapis.com/drive/v3/files?q=" + encodeURIComponent(q) + "&fields=" + encodeURIComponent("files(id,name,mimeType,parents,webViewLink,modifiedTime,size)") + "&orderBy=folder,name&pageSize=100";
    const res = await fetch(url, { headers: { "Authorization": "Bearer " + googleOAuthAccessToken } });
    if (!res.ok) return;
    const data = await res.json();
    const items = data.files || [];
    driveCurrentFolders = items.filter(i => i.mimeType === "application/vnd.google-apps.folder");
    driveCurrentFiles = items.filter(i => i.mimeType !== "application/vnd.google-apps.folder").map(item => {
      const m = String(item.mimeType || "");
      let typeLabel = "Drive File";
      if (m === "application/vnd.google-apps.document") typeLabel = "📄 Google Doc";
      else if (m === "application/vnd.google-apps.spreadsheet") typeLabel = "📊 Google Sheet";
      else if (m === "application/vnd.google-apps.presentation") typeLabel = "📽️ Google Slides";
      else if (m === "application/pdf") typeLabel = "📕 PDF";
      else if (m.startsWith("image/")) typeLabel = "🖼️ Image";
      return Object.assign({}, item, { typeLabel, linkedVaults: [] });
    });
    renderDriveBrowserList();
  } catch (e) {}
}

function openDriveBrowserModal(preselectVault) {
  document.getElementById("driveBrowserModal").classList.add("open");
  const validVaults = ["Education", "Business_Ideas", "LouLou_And_Luxe", "Projects", "Job_Hunt", "Expenses"];
  if (preselectVault && validVaults.includes(preselectVault)) {
    driveTargetVault = preselectVault;
  } else if (activeVaultFolder && validVaults.includes(activeVaultFolder)) {
    driveTargetVault = activeVaultFolder;
  } else {
    driveTargetVault = "Education";
  }
  selectDriveDestVault(driveTargetVault);
  document.getElementById("driveBrowserModalStatus").textContent = "";
  document.getElementById("driveBrowserModal").classList.add("open");
  if (driveCurrentFiles.length === 0 && driveCurrentFolders.length === 0) {
    if (driveTargetVault === "Education") {
      quickJumpDriveFolder("1G7XpHPUz-Us9HoH0FfrbhG0o3ZR1juW1", "Education");
    } else {
      loadDriveFolderContents("root", "");
    }
  } else {
    renderDriveBrowserList();
  }
}

function updateDriveTargetSubtextPreview() {
  const subInp = document.getElementById("driveTargetSubfolderInput");
  const subVal = subInp ? subInp.value.trim().replace(/[^A-Za-z0-9_\-\/ ]+/g, "").replace(/\s+/g, "_") : "";
  const fullDest = subVal ? `${driveTargetVault}/${subVal}` : driveTargetVault;
  const sub = document.getElementById("driveTargetVaultSubtext");
  if (sub) {
    sub.innerHTML = `Destination: <code>${escapeHtml(prettyVaultName(fullDest))}</code>`;
  }
}

function setDriveTargetSubfolder(subName) {
  const subInp = document.getElementById("driveTargetSubfolderInput");
  if (subInp) {
    subInp.value = subName;
    updateDriveTargetSubtextPreview();
    renderDriveExistingSubfolderPills();
  }
}

function renderDriveExistingSubfolderPills() {
  const bar = document.getElementById("driveExistingSubfoldersBar");
  if (!bar) return;
  const curSub = (document.getElementById("driveTargetSubfolderInput") ? document.getElementById("driveTargetSubfolderInput").value.trim() : "");
  const subs = getSubfoldersForVault(driveTargetVault);
  let h = `<button type="button" class="subfolder-pill ${curSub === '' ? 'active' : ''}" style="font-size:10.5px; padding:2px 8px;" onclick="setDriveTargetSubfolder('')">📌 Vault Root</button>`;
  for (const s of subs) {
    const safeS = s.replace(/'/g, "\\'");
    h += `<button type="button" class="subfolder-pill ${curSub === s ? 'active' : ''}" style="font-size:10.5px; padding:2px 8px;" onclick="setDriveTargetSubfolder('${safeS}')">📁 ${escapeHtml(s)}</button>`;
  }
  bar.innerHTML = h;
}

function selectDriveDestVault(vaultName) {
  driveTargetVault = vaultName;
  document.querySelectorAll("#driveVaultPromptGrid .vault-dest-btn").forEach(btn => {
    btn.classList.toggle("active", btn.getAttribute("data-dest") === vaultName);
  });
  const subInp = document.getElementById("driveTargetSubfolderInput");
  if (subInp && activeVaultFolder === vaultName && activeSubFolder && activeSubFolder !== "ALL" && activeSubFolder !== "__ROOT__") {
    subInp.value = activeSubFolder;
  }
  renderDriveExistingSubfolderPills();
  updateDriveTargetSubtextPreview();
}

function renderDriveBreadcrumbs() {
  const bar = document.getElementById("driveBreadcrumbsBar");
  if (!bar) return;
  bar.innerHTML = driveBreadcrumbs.map((c, idx) => {
    const sep = idx > 0 ? '<span style="color:var(--text-muted);">›</span>' : '';
    return sep + `<span class="drive-crumb" onclick="jumpToDriveBreadcrumb(${idx})">${escapeHtml(c.name)}</span>`;
  }).join(" ");
}

function jumpToDriveBreadcrumb(idx) {
  driveBreadcrumbs = driveBreadcrumbs.slice(0, idx + 1);
  document.getElementById("driveSearchInput").value = "";
  const cur = driveBreadcrumbs[driveBreadcrumbs.length - 1];
  renderDriveBreadcrumbs();
  loadDriveFolderContents(cur.id, "");
}

function quickJumpDriveFolder(folderId, folderName) {
  driveBreadcrumbs = [{ id: "root", name: "🏠 My Drive" }, { id: folderId, name: "📁 " + folderName }];
  document.getElementById("driveSearchInput").value = "";
  renderDriveBreadcrumbs();
  loadDriveFolderContents(folderId, "");
}

function browseDriveFolder(folderId, folderName) {
  driveBreadcrumbs.push({ id: folderId, name: "📁 " + folderName });
  document.getElementById("driveSearchInput").value = "";
  renderDriveBreadcrumbs();
  loadDriveFolderContents(folderId, "");
}

function resetDriveBrowserToRoot() {
  driveBreadcrumbs = [{ id: "root", name: "🏠 My Drive" }];
  document.getElementById("driveSearchInput").value = "";
  document.getElementById("driveTypeFilter").value = "all";
  renderDriveBreadcrumbs();
  loadDriveFolderContents("root", "");
}

function runDriveSearch() {
  const q = document.getElementById("driveSearchInput").value.trim();
  const cur = driveBreadcrumbs[driveBreadcrumbs.length - 1] || { id: "root" };
  loadDriveFolderContents(cur.id, q);
}

function reloadCurrentDriveView() {
  const q = document.getElementById("driveSearchInput").value.trim();
  const cur = driveBreadcrumbs[driveBreadcrumbs.length - 1] || { id: "root" };
  loadDriveFolderContents(cur.id, q);
}

async function loadDriveFolderContents(folderId, queryStr) {
  if (googleOAuthAccessToken && folderId !== '1G7XpHPUz-Us9HoH0FfrbhG0o3ZR1juW1' && folderId !== '173eDOYdvpj21_nlgnINbzsdGZoeINc90') {
    // Use backend unified view + OAuth token
  }
  const box = document.getElementById("driveBrowserListContainer");
  const filterType = document.getElementById("driveTypeFilter").value || "all";
  box.innerHTML = '<div style="padding:24px; text-align:center; color:var(--accent-bright);">🔄 Loading Google Drive items...</div>';
  try {
    const res = await fetch(DRIVE_BROWSE_ENDPOINT, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ folder_id: folderId, query: queryStr, filter_type: filterType })
    });
    const data = await res.json();
    driveCurrentFolders = data.folders || [];
    driveCurrentFiles = data.files || [];
    renderDriveBrowserList();
  } catch (e) {
    box.innerHTML = `<div style="padding:18px; color:var(--danger);">Failed to load Google Drive: ${escapeHtml(e.message)}</div>`;
  }
}

function updateDriveSelectionBadge() {
  const count = Object.keys(driveSelectedMap).length;
  const badge = document.getElementById("driveSelectionCountBadge");
  if (badge) {
    badge.textContent = count + (count === 1 ? " item selected" : " items selected");
  }
  const topBtn = document.getElementById("topConfirmDriveAddBtn");
  const botBtn = document.getElementById("confirmDriveAddBtn");
  const label = count > 0 ? `🚀 Add Selected to Vault (${count})` : "🚀 Add Selected to Vault";
  if (topBtn) topBtn.textContent = label;
  if (botBtn) botBtn.textContent = label;
}

function autoSuggestSubfolderForZip(f) {
  if (!f) return;
  if ((f.kind === "obsidian-zip" || /\.zip$/i.test(f.name || "")) && document.getElementById("driveTargetSubfolderInput")) {
    const subInp = document.getElementById("driveTargetSubfolderInput");
    if (!subInp.value.trim()) {
      const stem = String(f.name || "").replace(/\.zip$/i, "").replace(/^\d+_/, "").replace(/[^A-Za-z0-9_\- ]+/g, "").trim().replace(/\s+/g, "_");
      if (stem) {
        subInp.value = stem;
        updateDriveTargetSubtextPreview();
        renderDriveExistingSubfolderPills();
      }
    }
  }
}

function toggleDriveFolderSelect(folderId) {
  const fld = driveCurrentFolders.find(x => x.id === folderId);
  if (!fld) return;
  if (driveSelectedMap[folderId]) {
    delete driveSelectedMap[folderId];
  } else {
    driveSelectedMap[folderId] = fld;
  }
  updateDriveSelectionBadge();
  renderDriveBrowserList();
}

function toggleDriveFileSelect(fileId) {
  const f = driveCurrentFiles.find(x => x.id === fileId);
  if (!f) return;
  if (driveSelectedMap[fileId]) {
    delete driveSelectedMap[fileId];
  } else {
    driveSelectedMap[fileId] = f;
    autoSuggestSubfolderForZip(f);
  }
  updateDriveSelectionBadge();
  renderDriveBrowserList();
}

async function quickAddSingleDriveItem(itemId, isFolder) {
  const item = isFolder
    ? driveCurrentFolders.find(x => x.id === itemId)
    : driveCurrentFiles.find(x => x.id === itemId);
  if (!item) return;
  driveSelectedMap = {};
  driveSelectedMap[itemId] = item;
  if (!isFolder) autoSuggestSubfolderForZip(item);
  updateDriveSelectionBadge();
  renderDriveBrowserList();
  await submitSelectedDriveFilesToVault();
}

function selectAllVisibleDriveFiles() {
  for (const f of driveCurrentFiles) {
    driveSelectedMap[f.id] = f;
    autoSuggestSubfolderForZip(f);
  }
  updateDriveSelectionBadge();
  renderDriveBrowserList();
}

function clearDriveFileSelection() {
  driveSelectedMap = {};
  updateDriveSelectionBadge();
  renderDriveBrowserList();
}

function renderDriveBrowserList() {
  const box = document.getElementById("driveBrowserListContainer");
  if (!box) return;
  updateDriveSelectionBadge();

  let html = "";
  if (driveCurrentFolders.length === 0 && driveCurrentFiles.length === 0) {
    box.innerHTML = '<div style="padding:24px; text-align:center; color:var(--text-muted);">No matching folders or files in this view.</div>';
    return;
  }

  for (const fld of driveCurrentFolders) {
    const safeName = fld.name.replace(/'/g, "\\'");
    const isSel = Boolean(driveSelectedMap[fld.id]);
    html += `
      <div class="drive-item-row ${isSel ? 'selected' : ''}" onclick="browseDriveFolder('${fld.id}', '${safeName}')">
        <div style="display:flex; align-items:center; gap:10px; min-width:0; flex:1;">
          <input type="checkbox" ${isSel ? 'checked' : ''} style="width:18px; height:18px; accent-color:var(--accent); cursor:pointer; flex-shrink:0;" onclick="event.stopPropagation(); toggleDriveFolderSelect('${fld.id}')" title="Check to select entire folder" />
          <span style="font-size:16px;">📁</span>
          <div style="min-width:0; flex:1;">
            <div style="font-weight:600; font-size:13px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${escapeHtml(fld.name)}</div>
            <div style="font-size:10.5px; color:var(--text-muted);">Folder — Tap row to open, or tap '+ Add Folder' to import all files inside</div>
          </div>
        </div>
        <div style="display:flex; gap:5px; flex-shrink:0;">
          <button type="button" class="btn btn-sm" onclick="event.stopPropagation(); browseDriveFolder('${fld.id}', '${safeName}')">Open →</button>
          <button type="button" class="btn btn-success btn-sm" onclick="event.stopPropagation(); quickAddSingleDriveItem('${fld.id}', true)">➕ Add Folder</button>
        </div>
      </div>
    `;
  }

  for (const f of driveCurrentFiles) {
    const isSel = Boolean(driveSelectedMap[f.id]);
    const linkedBadges = (f.linkedVaults || []).map(v => `<span class="badge" style="background:rgba(16,185,129,0.18); color:#34d399; font-size:10px;">🔗 ${escapeHtml(prettyVaultName(v))}</span>`).join(" ");
    const modDate = f.modifiedTime ? f.modifiedTime.slice(0, 10) : "";
    const isZip = f.kind === "obsidian-zip" || /\.zip$/i.test(f.name || "");
    const actionLabel = isZip ? "📦 Unpack into Vault" : "➕ Add to Vault";
    html += `
      <div class="drive-item-row ${isSel ? 'selected' : ''}" onclick="toggleDriveFileSelect('${f.id}')">
        <div style="display:flex; align-items:center; gap:10px; min-width:0; flex:1;">
          <input type="checkbox" ${isSel ? 'checked' : ''} style="width:18px; height:18px; accent-color:var(--accent); pointer-events:none; flex-shrink:0;" />
          <div style="min-width:0; flex:1;">
            <div style="font-weight:600; font-size:13px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${escapeHtml(f.name)}</div>
            <div style="display:flex; align-items:center; gap:6px; flex-wrap:wrap; margin-top:2px;">
              <span style="font-size:10.5px; color:var(--accent-bright);">${escapeHtml(f.typeLabel || '📎 Drive File')}</span>
              ${modDate ? `<span style="font-size:10.5px; color:var(--text-muted);">• ${modDate}</span>` : ''}
              ${linkedBadges}
            </div>
          </div>
        </div>
        <div style="display:flex; gap:5px; align-items:center; flex-shrink:0;">
          <button type="button" class="btn btn-primary btn-sm" style="font-weight:700;" onclick="event.stopPropagation(); quickAddSingleDriveItem('${f.id}', false)">${actionLabel}</button>
          <a class="btn btn-sm" href="${escapeHtml(f.webViewLink)}" target="_blank" onclick="event.stopPropagation()" title="View original in Google Drive">↗</a>
        </div>
      </div>
    `;
  }

  box.innerHTML = html;
}

async function submitSelectedDriveFilesToVault() {
  const selectedList = Object.values(driveSelectedMap);
  const stEl = document.getElementById("driveBrowserModalStatus");
  if (selectedList.length === 0) {
    stEl.style.color = "#f87171";
    stEl.textContent = "⚠️ Check at least 1 file/folder below (or tap '➕ Add to Vault' directly on any row).";
    return;
  }

  const subInp = document.getElementById("driveTargetSubfolderInput");
  const subFolderVal = subInp ? subInp.value.trim().replace(/^\d+_/, "").replace(/[^A-Za-z0-9_\-\/ ]+/g, "").replace(/\s+/g, "_").replace(/^\/+|\/+$/g, "") : "";
  const hasZip = selectedList.some(x => x.kind === "obsidian-zip" || /\.zip$/i.test(x.name || ""));
  const destLabel = subFolderVal ? `${driveTargetVault}/${subFolderVal}` : driveTargetVault;

  const btn = document.getElementById("confirmDriveAddBtn");
  const topBtn = document.getElementById("topConfirmDriveAddBtn");
  if (btn) btn.disabled = true;
  if (topBtn) topBtn.disabled = true;
  stEl.style.color = "#a78bfa";
  stEl.textContent = hasZip
    ? `⏳ Downloading & unpacking Obsidian Vault (.zip) into ${prettyVaultName(destLabel)} (takes ~5-15s)...`
    : `⏳ Transforming & adding ${selectedList.length} item(s) into ${prettyVaultName(destLabel)}...`;

  try {
    const res = await fetch(DRIVE_IMPORT_ENDPOINT, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        target_folder: driveTargetVault,
        sub_folder: subFolderVal,
        selected_files: selectedList
      })
    });
    const data = await res.json();
    if (data && data.state) {
      STATE = data.state;
      driveSelectedMap = {};
      closeModal("driveBrowserModal");
      const finalFolder = data.target_vault_folder || destLabel;
      selectGlobalVault(finalFolder);
      showToast(`Added ${data.extracted_count || selectedList.length} note(s) into ${prettyVaultName(finalFolder)}!`);
      reloadCurrentDriveView();
    } else {
      stEl.style.color = "#f87171";
      stEl.textContent = "Import failed. Please try again.";
    }
  } catch (e) {
    stEl.style.color = "#f87171";
    stEl.textContent = "Error: " + e.message;
  } finally {
    if (btn) btn.disabled = false;
    if (topBtn) topBtn.disabled = false;
  }
}

async function syncDriveShortcutsNow() {
  const box = document.getElementById("driveExtractStatusBox");
  if (box) box.textContent = "⏳ Scanning Google Drive Vault Drop-Folders & resolving shortcuts...";
  showToast("Scanning Google Drive folders & shortcuts...");
  try {
    const res = await fetch(DRIVE_IMPORT_ENDPOINT, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ action: "scan_all_folders" })
    });
    const data = await res.json();
    if (data && data.state) {
      STATE = data.state;
      renderAll();
    }
    const cnt = (data && data.extracted_count) || 0;
    const msg = cnt > 0
      ? `✅ Extracted ${cnt} document(s) from Google Drive into your Obsidian Vault!`
      : `✅ Drive folders scanned (0 new shortcuts/docs found yet — drop any Google Doc/Sheet shortcut into your Drive folders to auto-extract).`;
    if (box) box.textContent = msg;
    showToast(msg);
  } catch (e) {
    if (box) box.textContent = "Error: " + e.message;
    showToast("Drive sync error: " + e.message, true);
  }
}

async function extractSingleGoogleDocUrl() {
  const url = document.getElementById("importDocUrl").value.trim();
  const folder = document.getElementById("importTargetFolder").value;
  const title = document.getElementById("importDocTitle").value.trim();
  if (!url) return showToast("Paste a Google Doc or Google Sheet URL first", true);

  const box = document.getElementById("driveExtractStatusBox");
  box.textContent = `⏳ Extracting document from Google Drive into ${folder}...`;
  try {
    const res = await fetch(DRIVE_IMPORT_ENDPOINT, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ doc_url: url, target_folder: folder, doc_title: title })
    });
    const data = await res.json();
    if (data && data.state) {
      STATE = data.state;
      renderAll();
    }
    document.getElementById("importDocUrl").value = "";
    document.getElementById("importDocTitle").value = "";
    box.textContent = `✅ Extracted & saved into ${folder}!`;
    selectGlobalVault(folder);
    showToast(`Loaded into ${folder}!`);
  } catch (e) {
    box.textContent = "Error: " + e.message;
    showToast("Failed: " + e.message, true);
  }
}

function renderAll() {
  renderDashboard();
  renderKanbanTab();
  renderJobsTab();
  renderExpensesTab();
  renderLearningTab();
}

function renderDashboard() {
  const openCards = STATE.cards.filter(c => !c.completed);
