function openCardModal(cardId = "", defBoard = "", defCol = "") {
  const bSel = document.getElementById("cmBoardId");
  bSel.innerHTML = STATE.boards.map(b => `<option value="${esc(b.board_id)}">${esc(b.title)}</option>`).join("");
  const ex = cardId ? STATE.cards.find(c => c.card_id === cardId) : null;
  document.getElementById("cmCardId").value = ex ? ex.card_id : "";
