function populateCardModalColumns(selCol = "") {
  const bid = document.getElementById("cmBoardId").value;
  const brd = STATE.boards.find(b => b.board_id === bid) || STATE.boards[0];
  const cols = brd ? (Array.isArray(brd.columns_json) ? brd.columns_json : JSON.parse(brd.columns_json || "[]")) : ["To Do", "In Progress", "Done"];
  const cSel = document.getElementById("cmColumn");
  cSel.innerHTML = cols.map(c => `<option value="${esc(c)}">${esc(c)}</option>`).join("");
  if (selCol && cols.includes(selCol)) cSel.value = selCol;
}

