function renderLearningTab() {
  const folderFilter = document.getElementById("vaultFolderFilter").value;
  const vaultNotes = folderFilter === "ALL"
    ? STATE.notes
    : STATE.notes.filter(n => getParentVaultOfNote(n) === folderFilter);

  // Build 2nd-Level Sub-Folder / Sub-Tab Bar
  const subBar = document.getElementById("vaultSubfolderBar");
  const subCounts = {};
  let rootCount = 0;
  for (const n of vaultNotes) {
    const sf = getSubfolderOfNote(n);
    if (sf) {
      subCounts[sf] = (subCounts[sf] || 0) + 1;
    } else {
      rootCount++;
    }
  }
  const subNames = Object.keys(subCounts).sort();
  if (activeSubFolder !== "ALL" && activeSubFolder !== "__ROOT__" && !subCounts[activeSubFolder]) {
    activeSubFolder = "ALL";
  }

  let subHtml = `<span style="font-size:11px; color:var(--text-muted); font-weight:700; margin-right:2px;">📁 Sub-Folders / Tabs:</span>`;
  subHtml += `<button type="button" class="subfolder-pill ${activeSubFolder === 'ALL' ? 'active' : ''}" onclick="selectVaultSubfolder('ALL')">📂 All (${vaultNotes.length})</button>`;
  if (subNames.length > 0 && rootCount > 0) {
    subHtml += `<button type="button" class="subfolder-pill ${activeSubFolder === '__ROOT__' ? 'active' : ''}" onclick="selectVaultSubfolder('__ROOT__')">📌 Vault Root (${rootCount})</button>`;
  }
  for (const sn of subNames) {
    const safeSn = sn.replace(/'/g, "\\'");
    subHtml += `<button type="button" class="subfolder-pill ${activeSubFolder === sn ? 'active' : ''}" onclick="selectVaultSubfolder('${safeSn}')">📁 ${esc(sn.replace(/_/g, " "))} (${subCounts[sn]})</button>`;
  }
  subHtml += `<button type="button" class="btn btn-sm" style="margin-left:auto; font-size:11px; padding:3px 9px;" onclick="openCreateSubfolderModal()">➕ New Sub-Folder</button>`;
  if (activeSubFolder !== "ALL" && activeSubFolder !== "__ROOT__" && folderFilter !== "ALL") {
    subHtml += `<button type="button" class="btn btn-danger btn-sm" style="font-size:11px; padding:3px 9px;" onclick="deleteActiveSubfolder()" title="Delete this Sub-Folder and its notes">🗑️ Delete Sub-Folder</button>`;
  }
  if (subBar) subBar.innerHTML = subHtml;

  // Filter by selected Sub-Folder
  const subFilteredNotes = vaultNotes.filter(n => {
    if (activeSubFolder === "ALL") return true;
    if (activeSubFolder === "__ROOT__") return getSubfolderOfNote(n) === "";
    return getSubfolderOfNote(n) === activeSubFolder;
  });

  // Build 3rd-Level Nested Course / Module Filter Bar (if notes inside this Sub-Folder have [Course/Module] prefixes)
  const courseBar = document.getElementById("vaultNestedCourseBar");
  const courseCounts = {};
  let overviewCount = 0;
  for (const n of subFilteredNotes) {
    const cn = getNestedCourseOfNote(n);
    if (cn) {
      courseCounts[cn] = (courseCounts[cn] || 0) + 1;
    } else {
      overviewCount++;
    }
  }
  const courseNames = Object.keys(courseCounts).sort();
  if (courseBar) {
    if (courseNames.length > 0) {
      if (activeNestedCourse !== "ALL" && activeNestedCourse !== "__OVERVIEW__" && !courseCounts[activeNestedCourse]) {
        activeNestedCourse = "ALL";
      }
      let cHtml = `<span style="font-size:11px; color:#34d399; font-weight:700; margin-right:4px;">📚 Modules / Courses:</span>`;
      cHtml += `<button type="button" class="course-pill ${activeNestedCourse === 'ALL' ? 'active' : ''}" onclick="selectNestedCourseFilter('ALL')">All (${subFilteredNotes.length})</button>`;
      if (overviewCount > 0) {
        cHtml += `<button type="button" class="course-pill ${activeNestedCourse === '__OVERVIEW__' ? 'active' : ''}" onclick="selectNestedCourseFilter('__OVERVIEW__')">🧭 Master Index / Overview (${overviewCount})</button>`;
      }
      for (const cn of courseNames) {
        const safeCn = cn.replace(/'/g, "\\'");
        cHtml += `<button type="button" class="course-pill ${activeNestedCourse === cn ? 'active' : ''}" onclick="selectNestedCourseFilter('${safeCn}')">📘 ${esc(cn)} (${courseCounts[cn]})</button>`;
      }
      courseBar.style.display = "flex";
      courseBar.innerHTML = cHtml;
    } else {
      courseBar.style.display = "none";
      courseBar.innerHTML = "";
      activeNestedCourse = "ALL";
    }
  }

  const filteredNotes = subFilteredNotes.filter(n => {
    if (activeNestedCourse === "ALL") return true;
    if (activeNestedCourse === "__OVERVIEW__") return getNestedCourseOfNote(n) === "";
    return getNestedCourseOfNote(n) === activeNestedCourse;
  });

  const sel = document.getElementById("vaultNoteSelect");
  const pillsBar = document.getElementById("vaultNotePillsBar");
  const readerBox = document.getElementById("vaultReaderViewBox");

  const headerSuffix = (activeSubFolder !== "ALL" && activeSubFolder !== "__ROOT__")
    ? `${prettyVaultName(folderFilter)} › ${prettyVaultName(activeSubFolder)}`
    : prettyVaultName(folderFilter);
  document.getElementById("vaultReaderHeaderTitle").textContent = `📖 Vault Reader — ${headerSuffix}`;

  if (filteredNotes.length) {
    if (!filteredNotes.find(n => n.note_id === selectedNoteId)) selectedNoteId = filteredNotes[0].note_id;
    sel.innerHTML = filteredNotes.map(n => { const t = n.title.replace(/^\d+_/, ""); return `<option value="${esc(n.note_id)}">${esc(t.length > 68 ? t.slice(0, 68) + "…" : t)}</option>`; }).join("");
    sel.value = selectedNoteId;

    // Show up to 40 note pills so huge .zip vaults stay snappy
    const pillSubset = filteredNotes.slice(0, 40);
    pillsBar.innerHTML = pillSubset.map(n => `
      <button class="board-pill ${n.note_id === selectedNoteId ? 'active' : ''}" onclick="selectVaultNote('${esc(n.note_id)}')">
        📄 ${esc(n.title.replace(/^Guide — Where to Put /, ''))}
      </button>
    `).join("") + (filteredNotes.length > 40 ? `<span style="font-size:11px; color:var(--text-muted); align-self:center; padding:0 6px;">+${filteredNotes.length - 40} more in dropdown ↓</span>` : "");

    const cur = filteredNotes.find(n => n.note_id === selectedNoteId);
    if (cur) {
      readerBox.innerHTML = renderMarkdownToHtml(cur.content_md);
      if (document.activeElement !== document.getElementById("vaultNoteContent")) {
        document.getElementById("vaultNoteFolder").value = getParentVaultOfNote(cur);
        const subInp = document.getElementById("vaultNoteSubfolder");
        if (subInp) subInp.value = getSubfolderOfNote(cur);
        document.getElementById("vaultNoteTitle").value = cur.title;
        document.getElementById("vaultNoteContent").value = cur.content_md;
      }
    }
  } else {
    sel.innerHTML = `<option value="">No notes in ${esc(headerSuffix)} yet</option>`;
    pillsBar.innerHTML = "";
    readerBox.innerHTML = `<div style="color:var(--text-muted);">No documents in <strong>${esc(headerSuffix)}</strong> yet. Tap <strong>📂 + Add from Drive (.zip / Docs)</strong> or <strong>+ New Note</strong> above.</div>`;
    document.getElementById("vaultNoteTitle").value = "";
    document.getElementById("vaultNoteContent").value = "";
  }

  const box = document.getElementById("flashcardPlayerBox");
  if (!STATE.flashcards.length) {
    box.innerHTML = `<div style="font-size:12px; color:var(--text-muted);">No flashcards yet. Click '+ Add Card' to create flashcards from your study notes.</div>`;
  } else {
    if (currentFcIndex >= STATE.flashcards.length) currentFcIndex = 0;
    const fc = STATE.flashcards[currentFcIndex];
    box.innerHTML = `
      <div style="background:var(--bg-elevated); padding:14px; border-radius:10px;">
        <div style="font-size:11px; color:var(--text-muted);">Deck: ${esc(fc.deck)} (${currentFcIndex + 1}/${STATE.flashcards.length})</div>
        <div style="font-size:14px; font-weight:700; margin:10px 0;">Q: ${esc(fc.question)}</div>
        ${fcShowAnswer ? `
          <div style="padding:10px; background:var(--bg-card); border-left:3px solid var(--accent); margin-bottom:10px;">${esc(fc.answer)}</div>
          <div style="display:flex; gap:6px;">
            <button class="btn btn-danger btn-sm" onclick="gradeFc('${esc(fc.card_id)}','again')">Again</button>
            <button class="btn btn-primary btn-sm" onclick="gradeFc('${esc(fc.card_id)}','good')">Good</button>
            <button class="btn btn-success btn-sm" onclick="gradeFc('${esc(fc.card_id)}','easy')">Easy</button>
          </div>
        ` : `<button class="btn btn-primary btn-sm" onclick="fcShowAnswer=true; renderLearningTab();">👁️ Show Answer</button>`}
      </div>
    `;
  }
}

