async function saveSelectedVaultNote() {
  const parentVault = document.getElementById("vaultNoteFolder").value || "Education";
  const subRaw = (document.getElementById("vaultNoteSubfolder") ? document.getElementById("vaultNoteSubfolder").value : "").trim();
  const cleanSub = subRaw.replace(/[^A-Za-z0-9_\-\/ ]+/g, "").trim().replace(/\s+/g, "_").replace(/^\/+|\/+$/g, "");
  const folder = cleanSub ? `${parentVault}/${cleanSub}` : parentVault;
  const title = document.getElementById("vaultNoteTitle").value.trim() || "Note";
  const slug = title.replace(/[^A-Za-z0-9_\- ]+/g, "").trim().replace(/\s+/g, "_") || "Note";
  await apiCall({
    action: "save_note",
    note_id: selectedNoteId || ("note-" + Date.now().toString(36)),
    folder, title,
    file_path: `${folder}/${slug}.md`,
