    exportUrl = `https://www.googleapis.com/drive/v3/files/${item.targetId}?alt=media`;
    sourceKind = 'obsidian-zip';
  } else if (m === 'application/vnd.google-apps.document') {
    exportUrl = `https://www.googleapis.com/drive/v3/files/${item.targetId}/export?mimeType=text/plain`;
    sourceKind = 'google-doc';
  } else if (m === 'application/vnd.google-apps.spreadsheet') {
    exportUrl = `https://www.googleapis.com/drive/v3/files/${item.targetId}/export?mimeType=text/csv`;
    sourceKind = 'google-sheet';
  } else if (m === 'application/vnd.google-apps.presentation') {
    exportUrl = `https://www.googleapis.com/drive/v3/files/${item.targetId}/export?mimeType=text/plain`;
    sourceKind = 'google-slides';
  } else if (m === 'application/pdf' || /\.pdf$/i.test(nm)) {
    exportUrl = fileSize > 35000000
      ? `https://www.googleapis.com/drive/v3/files/${item.targetId}?fields=id,name,mimeType,size,webViewLink,modifiedTime`
      : `https://www.googleapis.com/drive/v3/files/${item.targetId}?alt=media`;
    sourceKind = 'pdf-document';
  } else if (m.startsWith('image/') || /\.(png|jpg|jpeg|webp|gif|svg)$/i.test(nm)) {
    exportUrl = fileSize > 25000000
      ? `https://www.googleapis.com/drive/v3/files/${item.targetId}?fields=id,name,mimeType,size,webViewLink,modifiedTime`
      : `https://www.googleapis.com/drive/v3/files/${item.targetId}?alt=media`;
    sourceKind = 'image-file';
  } else if (
    m.includes('spreadsheetml') || m.includes('wordprocessingml') || m.includes('presentationml') ||
    m.startsWith('text/') || m === 'application/json' ||
    /\.(md|markdown|txt|csv|tsv|canvas|xlsx|xls|docx|doc|pptx|ppt)$/i.test(nm)
  ) {
    exportUrl = `https://www.googleapis.com/drive/v3/files/${item.targetId}?alt=media`;
    if (/\.(xlsx|xls|csv|tsv)$/i.test(nm) || m.includes('spreadsheetml') || m === 'text/csv') sourceKind = 'excel-sheet';
    else if (/\.(docx|doc)$/i.test(nm) || m.includes('wordprocessingml')) sourceKind = 'word-doc';
    else if (/\.(pptx|ppt)$/i.test(nm) || m.includes('presentationml')) sourceKind = 'powerpoint-slides';
    else sourceKind = 'text-file';
  } else {
    exportUrl = `https://www.googleapis.com/drive/v3/files/${item.targetId}?fields=id,name,mimeType,size,webViewLink,modifiedTime`;
    sourceKind = 'drive-file';
  }

  let link = item.webViewLink || '';
  if (!link) {
    if (sourceKind === 'google-sheet') link = `https://docs.google.com/spreadsheets/d/${item.targetId}/edit`;
    else if (sourceKind === 'google-doc') link = `https://docs.google.com/document/d/${item.targetId}/edit`;
    else if (sourceKind === 'google-slides') link = `https://docs.google.com/presentation/d/${item.targetId}/edit`;
    else link = `https://drive.google.com/file/d/${item.targetId}/view`;
  }

  queue.push({
    json: {
      skipExport: false,
      fileId: item.fileId || item.targetId,
      targetId: item.targetId,
      title: String(item.title || 'Imported File'),
      baseVault: (item.baseVault || (item.vaultFolder || targetVaultDefault).split('/')[0]).replace(/^\d+_/, ''),
      subFolder: item.subFolder || (item.vaultFolder || '').split('/').slice(1).join('/'),
      vaultFolder: (item.vaultFolder || targetVaultDefault).replace(/^\d+_/, ''),
