async function getItemBuffer(ctx, idx, item) {
  try {
    if (item && item.binary && item.binary.data) {
      try {
        const b = await ctx.helpers.getBinaryDataBuffer(idx, 'data');
        if (b && b.length > 0) return b;
      } catch (e) {}
      if (item.binary.data.data) {
        return Buffer.from(item.binary.data.data, 'base64');
      }
    }
  } catch (e) {}
  if (item && item.json) {
    if (typeof item.json === 'string') return Buffer.from(item.json, 'utf8');
    if (typeof item.json.data === 'string') return Buffer.from(item.json.data, 'utf8');
    return Buffer.from(JSON.stringify(item.json), 'utf8');
  }
  return Buffer.alloc(0);
}

