        linkedVaults: linkedMap[item.id] || []
      });
      continue;
    }
    folders.push({
      id: item.id,
      name: item.name,
      mimeType: item.mimeType,
      modifiedTime: item.modifiedTime || '',
      linkedVaults: linkedMap[item.id] || []
    });
  } else {
    let kind = 'file';
    let typeLabel = '📎 Drive File';
    const m = String(item.mimeType || '');
    const nm = String(item.name || '');
    const sizeMb = item.size ? (Number(item.size) >= 1048576 ? (Number(item.size) / 1048576).toFixed(1) + ' MB' : (Number(item.size) / 1024).toFixed(0) + ' KB') : '';
    if (m === 'application/zip' || m === 'application/x-zip-compressed' || /\.zip$/i.test(nm)) {
      kind = 'obsidian-zip';
      typeLabel = '📦 Obsidian Vault (.zip)' + (sizeMb ? ' • ' + sizeMb : '');
    } else if (m === 'text/markdown' || /\.(md|markdown|canvas)$/i.test(nm)) {
      kind = 'markdown-file';
      typeLabel = '📝 Obsidian Markdown (.md)';
    } else if (m === 'application/vnd.google-apps.document') {
      kind = 'google-doc';
      typeLabel = '📄 Google Doc';
    } else if (m === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' || /\.(docx|doc)$/i.test(nm)) {
      kind = 'word-doc';
      typeLabel = '📄 Word Doc (.docx)' + (sizeMb ? ' • ' + sizeMb : '');
    } else if (m === 'application/vnd.google-apps.spreadsheet') {
      kind = 'google-sheet';
      typeLabel = '📊 Google Sheet';
    } else if (m === 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' || /\.(xlsx|xls|csv)$/i.test(nm)) {
      kind = 'excel-sheet';
      typeLabel = '📊 Spreadsheet (.xlsx/.csv)' + (sizeMb ? ' • ' + sizeMb : '');
    } else if (m === 'application/vnd.google-apps.presentation' || m === 'application/vnd.openxmlformats-officedocument.presentationml.presentation' || /\.(pptx|ppt)$/i.test(nm)) {
      kind = 'google-slides';
      typeLabel = '📽️ Slides / Presentation';
    } else if (m === 'application/pdf' || /\.pdf$/i.test(nm)) {
      kind = 'pdf-document';
      typeLabel = '📕 PDF Document' + (sizeMb ? ' • ' + sizeMb : '');
    } else if (m.startsWith('image/') || /\.(png|jpg|jpeg|webp|gif|svg)$/i.test(nm)) {
      kind = 'image-file';
      typeLabel = '🖼️ Image' + (sizeMb ? ' • ' + sizeMb : '');
    } else if (m.startsWith('text/')) {
      kind = 'text-file';
      typeLabel = '📝 Text File';
    }

    files.push({
      id: item.id,
      name: item.name,
      mimeType: m,
      kind,
      typeLabel,
      webViewLink: item.webViewLink || `https://drive.google.com/file/d/${item.id}/view`,
      modifiedTime: item.modifiedTime || '',
      size: item.size || null,
      linkedVaults: linkedMap[item.id] || []
    });
  }
}

return [{
  json: {
    ok: true,
    folder_id: meta.folderId,
    query: meta.rawQuery,
    folders,
    files
  }
}];

const body = $('Webhook: Drive Shortcut Extractor').first().json.body || {};
const selectedFiles = Array.isArray(body.selected_files) ? body.selected_files : [];
const selectedFolders = selectedFiles.filter(f => f && f.mimeType === 'application/vnd.google-apps.folder');

if (selectedFolders.length === 0) {
  return [{
    json: {
      hasFolders: false,
      expandUrl: 'https://www.googleapis.com/drive/v3/about?fields=user'
    }
  }];
}

const pClauses = selectedFolders.map(f => `'${String(f.id).replace(/[^A-Za-z0-9_\-]/g, '')}' in parents`).join(' or ');
const q = encodeURIComponent(`(${pClauses}) and trashed = false`);
const fields = encodeURIComponent('files(id,name,mimeType,parents,webViewLink,modifiedTime,size)');

return [{
  json: {
    hasFolders: true,
    expandUrl: `https://www.googleapis.com/drive/v3/files?q=${q}&fields=${fields}&pageSize=100`
  }
}];

const prevMeta = $('Code: Check Selected Folders to Expand').first().json;
const firstLevelResp = $input.first().json || {};
const children = firstLevelResp.files || [];
const subFolders = children.filter(f => f.mimeType === 'application/vnd.google-apps.folder' && f.name !== 'Downloadable Materials');

if (!prevMeta.hasFolders || subFolders.length === 0) {
  return [{
    json: {
      hasSubFolders: false,
      subExpandUrl: 'https://www.googleapis.com/drive/v3/about?fields=user'
    }
  }];
}

const pClauses = subFolders.map(f => `'${String(f.id).replace(/[^A-Za-z0-9_\-]/g, '')}' in parents`).join(' or ');
const q = encodeURIComponent(`(${pClauses}) and trashed = false and mimeType != 'application/vnd.google-apps.folder'`);
const fields = encodeURIComponent('files(id,name,mimeType,parents,webViewLink,modifiedTime,size)');

return [{
  json: {
    hasSubFolders: true,
    subExpandUrl: `https://www.googleapis.com/drive/v3/files?q=${q}&fields=${fields}&pageSize=100`
  }
}];
